import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.kOe0DhAP.js";const p=JSON.parse('{"title":"产品与交易规则","description":"结算规则必须在下单时明确，并能在事后复核。","frontmatter":{"title":"产品与交易规则","description":"结算规则必须在下单时明确，并能在事后复核。"},"headers":[],"relativePath":"08/0802/080002.md","filePath":"08/0802/080002.md"}'),o={name:"08/0802/080002.md"};function s(l,a,d,n,c,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<div class="doc-eyebrow">期权手册 / TGEX KNOWLEDGE BASE</div><h1 id="产品与交易规则" tabindex="-1">产品与交易规则 <a class="header-anchor" href="#产品与交易规则" aria-label="Permalink to &quot;产品与交易规则&quot;">​</a></h1><div class="doc-lead">结算规则必须在下单时明确，并能在事后复核。</div><h2 id="direction" tabindex="-1">方向与期限 <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;方向与期限 {#direction}&quot;">​</a></h2><p>已检查的版本包含看涨、看跌、看平等结果定义，触碰版本还使用方向阈值及周期高低价。可选择方向、周期起止与可购买窗口应按产品分别列出。</p><h2 id="limits" tabindex="-1">下单条件与限额 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;下单条件与限额 {#limits}&quot;">​</a></h2><p>下单需要检查账户、币种、金额范围、周期状态及产品是否开放。截止时间应基于服务端权威时间；客户端倒计时只用于展示，不能作为受理依据。</p><h2 id="result" tabindex="-1">结果与收益规则 <a class="header-anchor" href="#result" aria-label="Permalink to &quot;结果与收益规则 {#result}&quot;">​</a></h2><p>到期比较开收盘、期间触碰阈值和其他判定方式是不同产品规则。尤其“到期价格没超过阈值”不能证明“期间从未触碰阈值”。</p><p>演算示例：假设投入 100 USDT，赢时净收益率 80%，规则约定返本金，则赢时总入账 180 USDT。若输时不返本金则入账为 0。此处仅解释本金、净收益与总返还的区别，不代表本项目所有期权产品的固定收益规则。</p>',10)])])}const m=e(o,[["render",s]]);export{p as __pageData,m as default};
